    ('US', 'PT10', 'wall', 'Shaft wall 2-1/2" CH stud @ 24" · 1" shaftliner + 2× 5/8" Type X · 2 hr', '#10B981'),
    ('US', 'PT11', 'wall', 'Exterior 6" 18 ga @ 16" · 5/8" exterior sheathing + 5/8" Type X · R-19', '#1E293B'),
    ('US', 'PT12', 'wall', 'Chase wall double 2-1/2" 25 ga @ 16" · 1× 5/8" Type X each side', '#65A30D')
),
targets as (
  select w.id, coalesce(w.framing->>'color', '') as old_color, v.color
    from public.takeoff_wall_types w
    join v on w.country_code = v.country and upper(w.code) = v.code
           and ((v.kind = 'wall' and w.category not in ('ceiling', 'floor')) or w.category = v.kind)
   where w.project_id is null
     and (w.organization_id is null
          or (w.category in ('ceiling', 'floor') and w.name = v.name and upper(coalesce(w.framing->>'color', '')) in ('#7C3AED', '#B7791F')))
     and upper(coalesce(w.framing->>'color', '')) <> upper(v.color)
),
layers as (
  update public.takeoff_layers l
     set color = t.color
    from targets t
   where l.wall_type_id = t.id and upper(l.color) = upper(t.old_color)
  returning l.id
)
update public.takeoff_wall_types w
   set framing = jsonb_set(coalesce(w.framing, '{}'::jsonb), '{color}', to_jsonb(t.color))
  from targets t
 where w.id = t.id;
